{-| @Backend.Runtime.Host.Lanes — packed binary64 lanes held in byte sequences, as `Pudu.Runtime.Lanes` and `Pudu.Eval.Builtin.Lanes` answer them. A kernel that finds its operands outside what it takes leaves state 2, which is None. -}
module Pudu.Backend.Runtime.Host.Lanes (hostLaneParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
hostLaneParts :: [(Text, [Text], [Text])]
hostLaneParts =
  [ ("host_lanes", ["host_optional", "host_math", "host_done", "kernel_fresh", "kernel_signed", "bytes_wrap"],
      [ "/* A product and a sum stay two roundings, as the interpreter computes them. */"
      , "#if defined(__clang__)"
      , "#pragma STDC FP_CONTRACT OFF"
      , "#endif"
      , "/* How many lanes a byte sequence holds, one lane read, and a new sequence"
      , "   of count lanes to write into. Lanes sit in the machine's own byte order"
      , "   and at any address. */"
      , "PUDU_OPTIONAL static inline size_t pudu_lanes_held(pudu_box *lanes) { return lanes->fields[0].text.length / 8; }"
      , "PUDU_OPTIONAL static inline double pudu_lanes_at(pudu_box *lanes, size_t index) {"
      , "  double value;"
      , "  memcpy(&value, lanes->fields[0].text.bytes + index * 8, 8);"
      , "  return value;"
      , "}"
      , "PUDU_OPTIONAL static inline void pudu_lanes_put(unsigned char *bytes, size_t index, double value) { memcpy(bytes + index * 8, &value, 8); }"
      , "PUDU_OPTIONAL static inline pudu_box *pudu_lanes_new(size_t count, unsigned char **bytes) {"
      , "  if (count > SIZE_MAX / 8) pudu_memory_failure();"
      , "  return pudu_bytes_wrap(pudu_kernel_fresh(count * 8, bytes));"
      , "}"
      , "PUDU_OPTIONAL static inline pudu_box *pudu_lanes_none(void) { pudu_host_done(2); return NULL; }"
      , "PUDU_OPTIONAL static inline double pudu_lanes_smaller(double x, double y) { return isnan(x) ? y : y < x ? y : x; }"
      , "PUDU_OPTIONAL static inline double pudu_lanes_larger(double x, double y) { return isnan(x) ? y : y > x ? y : x; }"
      , "/* A written index or count as a place in memory, or -1 outside what one can be. */"
      , "PUDU_OPTIONAL static inline int64_t pudu_lanes_place(pudu_int written) {"
      , "  int64_t value = pudu_kernel_signed(written.bits);"
      , "  return written.negative || value < 0 ? -1 : value;"
      , "}"
      ])
  , ("host_lanes_whole", [],
      [ "/* Whether the bytes are whole binary64 values. */"
      , "static inline int pudu_host_lanes_whole(pudu_box *lanes) { return lanes->fields[0].text.length % 8 == 0; }"
      ])
  , ("host_lanes_fill", ["host_lanes", "float_decode"],
      [ "static pudu_box *pudu_host_lanes_fill(pudu_int count, uint64_t value) {"
      , "  int64_t wanted = pudu_kernel_signed(count.bits);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made;"
      , "  if (wanted < 0) return pudu_lanes_none();"
      , "  made = pudu_lanes_new((size_t)wanted, &bytes);"
      , "  for (size_t i = 0; i < (size_t)wanted; ++i) pudu_lanes_put(bytes, i, pudu_float_decode(value));"
      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_ramp", ["host_lanes", "float_decode"],
      [ "static pudu_box *pudu_host_lanes_ramp(pudu_int count, uint64_t start, uint64_t step) {"
      , "  int64_t wanted = pudu_kernel_signed(count.bits);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made;"
      , "  if (wanted < 0) return pudu_lanes_none();"
      , "  made = pudu_lanes_new((size_t)wanted, &bytes);"
      , "  for (size_t i = 0; i < (size_t)wanted; ++i) pudu_lanes_put(bytes, i, pudu_float_decode(start) + (double)i * pudu_float_decode(step));"
      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_from_array", ["host_lanes", "array", "float_decode"],
      [ "/* Mode 0 packs floats; mode 1 packs integers as the floats nearest them. */"
      , "static pudu_box *pudu_host_lanes_from_array(pudu_box *items, int mode) {"
      , "  size_t count = pudu_array_length(items);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made = pudu_lanes_new(count, &bytes);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    pudu_cell item = items->fields[0].items->cells[i];"
      , "    pudu_lanes_put(bytes, i, mode == 0 ? pudu_float_decode(item.floating) : (double)pudu_kernel_signed(item.integer.bits));"
      , "  }"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_to_array", ["host_lanes", "array", "float_encode"],
      [ "static pudu_box *pudu_host_lanes_to_array(pudu_box *lanes) {"
      , "  size_t count = pudu_lanes_held(lanes);"
      , "  pudu_box *array = pudu_array_new(count);"
      , "  for (size_t i = 0; i < count; ++i) array->fields[0].items->cells[i].floating = pudu_float_encode(pudu_lanes_at(lanes, i));"
      , "  pudu_array_length(array) = count;"
      , "  return array;"
      , "}"
      ])
  , ("host_lanes_count", ["host_lanes", "kernel_int"],
      [ "static pudu_int pudu_host_lanes_count(pudu_box *lanes) { return pudu_kernel_int((int64_t)pudu_lanes_held(lanes)); }"
      ])
  , ("host_lanes_get", ["host_lanes", "float_encode"],
      [ "static uint64_t pudu_host_lanes_get(pudu_box *lanes, pudu_int index) {"
      , "  int64_t place = pudu_lanes_place(index);"
      , "  if (place < 0 || (uint64_t)place >= pudu_lanes_held(lanes)) { pudu_host_done(2); return 0; }"
      , "  pudu_host_done(0);"
      , "  return pudu_float_encode(pudu_lanes_at(lanes, (size_t)place));"
      , "}"
      ])
  , ("host_lanes_set", ["host_lanes", "float_decode"],
      [ "static pudu_box *pudu_host_lanes_set(pudu_box *lanes, pudu_int index, uint64_t value) {"
      , "  int64_t place = pudu_lanes_place(index);"
      , "  size_t count = pudu_lanes_held(lanes);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made;"
      , "  if (place < 0 || (uint64_t)place >= count) return pudu_lanes_none();"
      , "  made = pudu_lanes_new(count, &bytes);"
      , "  if (count != 0) memcpy(bytes, lanes->fields[0].text.bytes, count * 8);"
      , "  pudu_lanes_put(bytes, (size_t)place, pudu_float_decode(value));"
      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_slice", ["host_lanes"],
      [ "static pudu_box *pudu_host_lanes_slice(pudu_box *lanes, pudu_int start, pudu_int count) {"
      , "  int64_t from = pudu_lanes_place(start), taken = pudu_lanes_place(count);"
      , "  size_t held = pudu_lanes_held(lanes);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made;"
      , "  if (from < 0 || taken < 0 || (uint64_t)from > held || (uint64_t)taken > held - (uint64_t)from) return pudu_lanes_none();"
      , "  made = pudu_lanes_new((size_t)taken, &bytes);"
      , "  if (taken != 0) memcpy(bytes, lanes->fields[0].text.bytes + (size_t)from * 8, (size_t)taken * 8);"
      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_concat", ["host_lanes"],
      [ "static pudu_box *pudu_host_lanes_concat(pudu_box *left, pudu_box *right) {"
      , "  pudu_text a = left->fields[0].text, b = right->fields[0].text;"
      , "  unsigned char *bytes;"
      , "  pudu_text joined;"
      , "  if (a.length > SIZE_MAX - b.length) pudu_memory_failure();"
      , "  joined = pudu_kernel_fresh(a.length + b.length, &bytes);"
      , "  if (a.length != 0) memcpy(bytes, a.bytes, a.length);"
      , "  if (b.length != 0) memcpy(bytes + a.length, b.bytes, b.length);"
      , "  return pudu_bytes_wrap(joined);"
      , "}"
      ])
  , ("host_lanes_zip", ["host_lanes"],
      [ "/* Lane by lane over two sequences of one length: 0 add, 1 subtract,"
      , "   2 multiply, 3 divide, 4 the smaller, 5 the larger. */"
      , "static pudu_box *pudu_host_lanes_zip(pudu_box *left, pudu_box *right, int mode) {"
      , "  size_t count = pudu_lanes_held(left);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made;"
      , "  if (count != pudu_lanes_held(right)) return pudu_lanes_none();"
      , "  made = pudu_lanes_new(count, &bytes);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    double x = pudu_lanes_at(left, i), y = pudu_lanes_at(right, i);"
      , "    pudu_lanes_put(bytes, i, mode == 0 ? x + y : mode == 1 ? x - y : mode == 2 ? x * y : mode == 3 ? x / y"
      , "      : mode == 4 ? pudu_lanes_smaller(x, y) : pudu_lanes_larger(x, y));"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_scalar", ["host_lanes", "float_decode"],
      [ "/* Each lane against one value: 0 add, 1 multiply, 2 one where the lane is above it. */"
      , "static pudu_box *pudu_host_lanes_scalar(pudu_box *lanes, uint64_t value, int mode) {"
      , "  size_t count = pudu_lanes_held(lanes);"
      , "  double scalar = pudu_float_decode(value);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made = pudu_lanes_new(count, &bytes);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    double x = pudu_lanes_at(lanes, i);"
      , "    pudu_lanes_put(bytes, i, mode == 0 ? x + scalar : mode == 1 ? x * scalar : x > scalar ? 1.0 : 0.0);"
      , "  }"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_clamp", ["host_lanes", "float_decode"],
      [ "static pudu_box *pudu_host_lanes_clamp(pudu_box *lanes, uint64_t low, uint64_t high) {"
      , "  size_t count = pudu_lanes_held(lanes);"
      , "  double least = pudu_float_decode(low), most = pudu_float_decode(high);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made = pudu_lanes_new(count, &bytes);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    double x = pudu_lanes_at(lanes, i);"
      , "    pudu_lanes_put(bytes, i, x < least ? least : x > most ? most : x);"
      , "  }"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_map", ["host_lanes"],
      [ "/* Each lane alone: 0 its size, 1 its negation, 2 its root, 3 its floor. */"
      , "static pudu_box *pudu_host_lanes_map(pudu_box *lanes, int mode) {"
      , "  size_t count = pudu_lanes_held(lanes);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made = pudu_lanes_new(count, &bytes);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    double x = pudu_lanes_at(lanes, i);"
      , "    pudu_lanes_put(bytes, i, mode == 0 ? fabs(x) : mode == 1 ? -x : mode == 2 ? sqrt(x) : floor(x));"
      , "  }"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_axpy", ["host_lanes", "float_decode"],
      [ "static pudu_box *pudu_host_lanes_axpy(pudu_box *base, uint64_t factor, pudu_box *added) {"
      , "  size_t count = pudu_lanes_held(base);"
      , "  double scale = pudu_float_decode(factor);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made;"
      , "  if (count != pudu_lanes_held(added)) return pudu_lanes_none();"
      , "  made = pudu_lanes_new(count, &bytes);"
      , "  for (size_t i = 0; i < count; ++i) pudu_lanes_put(bytes, i, pudu_lanes_at(base, i) + scale * pudu_lanes_at(added, i));"
      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_zip3", ["host_lanes"],
      [ "/* Over three sequences of one length: 0 first times second plus third,"
      , "   1 the second where the first is above zero and the third elsewhere. */"
      , "static pudu_box *pudu_host_lanes_zip3(pudu_box *first, pudu_box *second, pudu_box *third, int mode) {"
      , "  size_t count = pudu_lanes_held(first);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made;"
      , "  if (count != pudu_lanes_held(second) || count != pudu_lanes_held(third)) return pudu_lanes_none();"
      , "  made = pudu_lanes_new(count, &bytes);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    double x = pudu_lanes_at(first, i), y = pudu_lanes_at(second, i), z = pudu_lanes_at(third, i);"
      , "    volatile double product = x * y;"
      , "    pudu_lanes_put(bytes, i, mode == 0 ? product + z : x > 0 ? y : z);"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_sum", ["host_lanes", "float_encode"],
      [ "static uint64_t pudu_host_lanes_sum(pudu_box *lanes) {"
      , "  size_t count = pudu_lanes_held(lanes);"
      , "  double total = 0;"
      , "  for (size_t i = 0; i < count; ++i) total += pudu_lanes_at(lanes, i);"
      , "  return pudu_float_encode(total);"
      , "}"
      ])
  , ("host_lanes_dot", ["host_lanes", "float_encode"],
      [ "static uint64_t pudu_host_lanes_dot(pudu_box *left, pudu_box *right) {"
      , "  size_t count = pudu_lanes_held(left);"
      , "  double total = 0;"
      , "  if (count != pudu_lanes_held(right)) { pudu_host_done(2); return 0; }"
      , "  for (size_t i = 0; i < count; ++i) { volatile double product = pudu_lanes_at(left, i) * pudu_lanes_at(right, i); total += product; }"
      , "  pudu_host_done(0);"
      , "  return pudu_float_encode(total);"
      , "}"
      ])
  , ("host_lanes_extreme", ["host_lanes", "float_encode"],
      [ "/* The least lane (0) or the greatest (1); none in an empty sequence. */"
      , "static uint64_t pudu_host_lanes_extreme(pudu_box *lanes, int mode) {"
      , "  size_t count = pudu_lanes_held(lanes);"
      , "  double found;"
      , "  if (count == 0) { pudu_host_done(2); return 0; }"
      , "  found = pudu_lanes_at(lanes, 0);"
      , "  for (size_t i = 0; i < count; ++i) found = mode == 0 ? pudu_lanes_smaller(found, pudu_lanes_at(lanes, i)) : pudu_lanes_larger(found, pudu_lanes_at(lanes, i));"
      , "  pudu_host_done(0);"
      , "  return pudu_float_encode(found);"
      , "}"
      ])
  , ("host_lanes_gather", ["host_lanes", "array"],
      [ "static pudu_box *pudu_host_lanes_gather(pudu_box *lanes, pudu_box *indices) {"
