      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_scatter", ["host_lanes", "array"],
      [ "/* The lanes with fresh values written (0) or added (1) at the indices, in order. */"
      , "static pudu_box *pudu_host_lanes_scatter(pudu_box *lanes, pudu_box *indices, pudu_box *fresh, int mode) {"
      , "  size_t wanted = pudu_array_length(indices), held = pudu_lanes_held(lanes);"
      , "  unsigned char *bytes;"
      , "  pudu_box *made;"
      , "  if (wanted != pudu_lanes_held(fresh)) return pudu_lanes_none();"
      , "  for (size_t i = 0; i < wanted; ++i) {"
      , "    int64_t place = pudu_lanes_place(indices->fields[0].items->cells[i].integer);"
      , "    if (place < 0 || (uint64_t)place >= held) return pudu_lanes_none();"
      , "  }"
      , "  made = pudu_lanes_new(held, &bytes);"
      , "  if (held != 0) memcpy(bytes, lanes->fields[0].text.bytes, held * 8);"
