      , "    size_t place = (size_t)pudu_lanes_place(indices->fields[0].items->cells[i].integer);"
      , "    double value = pudu_lanes_at(fresh, i), before;"
      , "    memcpy(&before, bytes + place * 8, 8);"
      , "    pudu_lanes_put(bytes, place, mode == 0 ? value : before + value);"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return made;"
      , "}"
      ])
  , ("host_lanes_affine3", ["host_lanes", "array", "float_decode"],
      [ "/* Three sequences through a matrix of twelve entries, column by column. */"
      , "static pudu_box *pudu_host_lanes_affine3(pudu_box *matrix, pudu_box *xs, pudu_box *ys, pudu_box *zs) {"
      , "  size_t count = pudu_lanes_held(xs);"
      , "  double m[12];"
      , "  unsigned char *out[3];"
      , "  pudu_box *answer;"
      , "  if (pudu_array_length(matrix) != 12 || count != pudu_lanes_held(ys) || count != pudu_lanes_held(zs)) return pudu_lanes_none();"
      , "  for (size_t i = 0; i < 12; ++i) m[i] = pudu_float_decode(matrix->fields[0].items->cells[i].floating);"
      , "  answer = pudu_box_new(3);"
      , "  for (size_t row = 0; row < 3; ++row) answer->fields[row].box = pudu_lanes_new(count, &out[row]);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    double x = pudu_lanes_at(xs, i), y = pudu_lanes_at(ys, i), z = pudu_lanes_at(zs, i);"
      , "    for (size_t row = 0; row < 3; ++row) {"
      , "      volatile double a = m[row] * x, b = m[row + 3] * y, c = m[row + 6] * z;"
      , "      volatile double partial = a + b;"
      , "      partial = partial + c;"
      , "      pudu_lanes_put(out[row], i, partial + m[row + 9]);"
      , "    }"
      , "  }"
      , "  pudu_host_done(0);"
      , "  return answer;"
      , "}"
      ])
  , ("host_lanes_interleave", ["host_lanes"],
