      , "  for (size_t i = 0; i < count; ++i) { pudu_lanes_put(bytes, i * 2, pudu_lanes_at(left, i)); pudu_lanes_put(bytes, i * 2 + 1, pudu_lanes_at(right, i)); }"
      , "  pudu_host_done(0);"
