      ])
  , ("host_lanes_to_pcm16", ["host_lanes"],
      [ "/* Each lane as a signed sixteen-bit sample, low byte first; a lane outside"
      , "   one and minus one is held to them. */"
      , "static pudu_box *pudu_host_lanes_to_pcm16(pudu_box *lanes) {"
      , "  size_t count = pudu_lanes_held(lanes);"
      , "  unsigned char *bytes;"
      , "  pudu_text samples = pudu_kernel_fresh(count * 2, &bytes);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    double x = pudu_lanes_at(lanes, i);"
      , "    int sample = isnan(x) ? 0 : x >= 1 ? 32767 : x <= -1 ? -32767 : x >= 0 ? (int)(x * 32767 + 0.5) : -(int)(-x * 32767 + 0.5);"
      , "    int word = sample < 0 ? sample + 65536 : sample;"
      , "    bytes[i * 2] = (unsigned char)(word % 256);"
      , "    bytes[i * 2 + 1] = (unsigned char)(word / 256);"
      , "  }"
      , "  return pudu_bytes_wrap(samples);"
      , "}"
      ])
  , ("host_lanes_where", ["host_lanes", "array", "array_reserve", "kernel_int"],
      [ "/* The places whose lane is above zero. */"
      , "static pudu_box *pudu_host_lanes_where(pudu_box *mask) {"
      , "  size_t count = pudu_lanes_held(mask);"
      , "  pudu_box *array = pudu_array_new(0);"
      , "  for (size_t i = 0; i < count; ++i) {"
      , "    if (!(pudu_lanes_at(mask, i) > 0)) continue;"
      , "    pudu_array_reserve(array, pudu_array_length(array) + 1);"
      , "    array->fields[0].items->cells[pudu_array_length(array)].integer = pudu_kernel_int((int64_t)i);"
      , "    pudu_array_length(array) += 1;"
      , "  }"
      , "  return array;"
      , "}"
      ])
  , ("host_lanes_overlap_pairs", ["host_lanes", "array", "kernel_int", "memory_failure"],
      [ "/* Boxes sorted by minimum x, ties by index, then each swept against the"
      , "   boxes after it whose x interval still reaches it; touching boxes overlap."
      , "   Pairs are smaller index first, in ascending order, flattened. */"
      , "typedef struct { double x; size_t index; } pudu_lanes_start;"
      , "static int pudu_lanes_start_order(const void *a, const void *b) {"
